export enum ContextPriority {
  Critical = 'critical',
  High = 'high',
  Medium = 'medium',
  Low = 'low'
}

export interface AgentProfile {
  id: string;           // identificador único del agente
  name: string;         // nombre descriptivo
  role: AgentRole;
  capabilities: AgentCapability[];
  description?: string; // contexto adicional sobre el agente
  model?: string;       // modelo de IA (ej: 'claude-sonnet-4-6', 'gpt-4o')
}

Interface opcional para que los adaptadores reciban opciones estándar:

export interface ContextSourceOptions {
  priority?: ContextPriority;
  tags?: string[];
  agentFilter?: AgentRole[];
}

private agent: AgentProfile | undefined;

setAgent(agent: AgentProfile): void {
  this.agent = agent;
}

Asegurarse de que el export existente incluya los nuevos tipos:
export type { AgentProfile, AgentRole, AgentCapability, ContextSourceOptions } from './types';
